Ltac foe_xfer POST H :=
  lazymatch type of H with
  | rdn RSEGS _ ?a ?n = Some ?bs =>
      lazymatch type of POST with
      | foe_post ?m1 ?su ?m2 =>
          let H' := fresh H in
          assert (H' : rdn RSEGS m2 a n = Some bs);
          [ eapply (foe_post_rdn _ _ _ _ _ _ POST); [ unfold mem_w1; rdn_solve | zsimp; lia | zsimp; lia | zsimp; lia ]
          | clear H; rename H' into H ]
      end
  end.

